window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-596185dff4720a96"]={"versions": [{"id": "FIG-596185dff4720a96", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) zur Veranschaulichung der Definitionsstruktur von ECU-Konfigurationscontainern im Kontext der AUTOSAR-Parametrisierung (TPS ECU Configuration). Es zeigt die hierarchische Organisation von Modul- und Containerdefinitionen anhand von Instanzen der Metamodell-Klassen <code>EcucDefinitionCollection</code>, <code>EcucModuleDef</code> und <code>EcucParamConfContainerDef</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind fünf konkrete Spezifikationsobjekte mit ihren Attributwerten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AUTOSARParameterDefinition : EcucDefinitionCollection</code>: Wurzel-Definitionskollektion.\n</li><li><code>Rte : EcucModuleDef</code>: Moduldefinition für die RTE mit <code>upperMultiplicity = 1</code> und <code>lowerMultiplicity = 0</code>, assoziiert über die gerichtete Beziehung <code>+module</code>.\n</li><li><code>RteGeneration : EcucParamConfContainerDef</code>: Containerdefinition für Generierungseinstellungen mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>, aggregiert von <code>Rte</code> über Komposition <code>+container</code>.\n</li><li><code>RteSwComponentInstance : EcucParamConfContainerDef</code>: Containerdefinition für Softwarekomponenteninstanzen mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = *</code>, aggregiert von <code>Rte</code> über Komposition <code>+container</code>.\n</li><li><code>RteEventToTaskMapping : EcucParamConfContainerDef</code>: Untergeordnete Containerdefinition für Event-zu-Task-Mappings mit <code>upperMultiplicity = *</code> und <code>lowerMultiplicity = 0</code>, aggregiert von <code>RteSwComponentInstance</code> über Komposition <code>+subContainer</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne dynamische Sequenzabläufe. Es definiert die statische hierarchische Schachtelung und Multiplizitätsgrenzen bei der Instanziierung von Konfigurationsbeschreibungen ausgehend von der Parameterdefinition.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarisches Strukturdiagramm für Werkzeug- und Methodenentwickler zur Definition von ECU-Konfigurationsmetamodellen. Die spezifizierten Multiplizitäten (<code>lowerMultiplicity</code>, <code>upperMultiplicity</code>) steuern die Validierung der erlaubten Kardinalitäten von Konfigurationscontainern in nachgelagerten ECU-Konfigurationswerten (EcucValues). Mandatory-Container (<code>RteGeneration</code> mit Multiplizität 1..1) erfordern zwingend eine Ausprägung, während optionale/mehrfache Container (<code>0..*</code>) entsprechend abgebildet werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cbf14a86165725d1", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) zur Veranschaulichung der Definitionsstruktur von ECU-Konfigurationscontainern im Kontext der AUTOSAR-Parametrisierung (TPS ECU Configuration). Es zeigt die hierarchische Organisation von Modul- und Containerdefinitionen anhand von Instanzen der Metamodell-Klassen <code>EcucDefinitionCollection</code>, <code>EcucModuleDef</code> und <code>EcucParamConfContainerDef</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind fünf konkrete Spezifikationsobjekte mit ihren Attributwerten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AUTOSARParameterDefinition : EcucDefinitionCollection</code>: Wurzel-Definitionskollektion.\n</li><li><code>Rte : EcucModuleDef</code>: Moduldefinition für die RTE mit <code>upperMultiplicity = 1</code> und <code>lowerMultiplicity = 0</code>, assoziiert über die gerichtete Beziehung <code>+module</code>.\n</li><li><code>RteGeneration : EcucParamConfContainerDef</code>: Containerdefinition für Generierungseinstellungen mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>, aggregiert von <code>Rte</code> über Komposition <code>+container</code>.\n</li><li><code>RteSwComponentInstance : EcucParamConfContainerDef</code>: Containerdefinition für Softwarekomponenteninstanzen mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = *</code>, aggregiert von <code>Rte</code> über Komposition <code>+container</code>.\n</li><li><code>RteEventToTaskMapping : EcucParamConfContainerDef</code>: Untergeordnete Containerdefinition für Event-zu-Task-Mappings mit <code>upperMultiplicity = *</code> und <code>lowerMultiplicity = 0</code>, aggregiert von <code>RteSwComponentInstance</code> über Komposition <code>+subContainer</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne dynamische Sequenzabläufe. Es definiert die statische hierarchische Schachtelung und Multiplizitätsgrenzen bei der Instanziierung von Konfigurationsbeschreibungen ausgehend von der Parameterdefinition.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarisches Strukturdiagramm für Werkzeug- und Methodenentwickler zur Definition von ECU-Konfigurationsmetamodellen. Die spezifizierten Multiplizitäten (<code>lowerMultiplicity</code>, <code>upperMultiplicity</code>) steuern die Validierung der erlaubten Kardinalitäten von Konfigurationscontainern in nachgelagerten ECU-Konfigurationswerten (EcucValues). Mandatory-Container (<code>RteGeneration</code> mit Multiplizität 1..1) erfordern zwingend eine Ausprägung, während optionale/mehrfache Container (<code>0..*</code>) entsprechend abgebildet werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-518b031e3cc2ca41", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) zur Veranschaulichung der Definitionsstruktur von ECU-Konfigurationscontainern im Kontext der AUTOSAR-Parametrisierung (TPS ECU Configuration). Es zeigt die hierarchische Organisation von Modul- und Containerdefinitionen anhand von Instanzen der Metamodell-Klassen <code>EcucDefinitionCollection</code>, <code>EcucModuleDef</code> und <code>EcucParamConfContainerDef</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind fünf konkrete Spezifikationsobjekte mit ihren Attributwerten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>AUTOSARParameterDefinition : EcucDefinitionCollection</code>: Wurzel-Definitionskollektion.\n</li><li><code>Rte : EcucModuleDef</code>: Moduldefinition für die RTE mit <code>upperMultiplicity = 1</code> und <code>lowerMultiplicity = 0</code>, assoziiert über die gerichtete Beziehung <code>+module</code>.\n</li><li><code>RteGeneration : EcucParamConfContainerDef</code>: Containerdefinition für Generierungseinstellungen mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 1</code>, aggregiert von <code>Rte</code> über Komposition <code>+container</code>.\n</li><li><code>RteSwComponentInstance : EcucParamConfContainerDef</code>: Containerdefinition für Softwarekomponenteninstanzen mit <code>lowerMultiplicity = 0</code> und <code>upperMultiplicity = *</code>, aggregiert von <code>Rte</code> über Komposition <code>+container</code>.\n</li><li><code>RteEventToTaskMapping : EcucParamConfContainerDef</code>: Untergeordnete Containerdefinition für Event-zu-Task-Mappings mit <code>upperMultiplicity = *</code> und <code>lowerMultiplicity = 0</code>, aggregiert von <code>RteSwComponentInstance</code> über Komposition <code>+subContainer</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne dynamische Sequenzabläufe. Es definiert die statische hierarchische Schachtelung und Multiplizitätsgrenzen bei der Instanziierung von Konfigurationsbeschreibungen ausgehend von der Parameterdefinition.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarisches Strukturdiagramm für Werkzeug- und Methodenentwickler zur Definition von ECU-Konfigurationsmetamodellen. Die spezifizierten Multiplizitäten (<code>lowerMultiplicity</code>, <code>upperMultiplicity</code>) steuern die Validierung der erlaubten Kardinalitäten von Konfigurationscontainern in nachgelagerten ECU-Konfigurationswerten (EcucValues). Mandatory-Container (<code>RteGeneration</code> mit Multiplizität 1..1) erfordern zwingend eine Ausprägung, während optionale/mehrfache Container (<code>0..*</code>) entsprechend abgebildet werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-596185dff4720a96", "to": "FIG-cbf14a86165725d1", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cbf14a86165725d1", "to": "FIG-518b031e3cc2ca41", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
